set definition = '{"version":1,"pages":[{"title":"איך מזהים ומנסחים רעיון מרכזי","intro":"לפני התרגול — שלושה צעדים, שני מושגים ודוגמה אחת מודגמת.","blocks":[{"kind":"steps","title":"שלושת הצעדים","steps":[{"title":"צעד 1: על מה הפסקה מדברת?","body":"עונים במילה אחת או בצירוף קצר — זה הנושא."},{"title":"צעד 2: מה היא אומרת על זה?","body":"עונים במשפט אחד — זה המסר."},{"title":"צעד 3: חברו את שני הדברים למשפט אחד","body":"משפט שלם אחד, במילים שלכם — לא העתקה מהטקסט."}]},{"kind":"terms","title":"שני מושגים שחשוב להבדיל ביניהם","terms":[{"title":"נושא","body":"על מה מדובר בפסקה. נענה במילה אחת או בצירוף קצר, בלי לומר מה נאמר על זה."},{"title":"מסר","body":"מה הפסקה אומרת על הנושא. זו העמדה או הקביעה שהכתוב מוביל אליה, במשפט שלם."}]},{"kind":"example","title":"דוגמה מודגמת","paragraph":"הרבה תלמידים מפחדים לדבר מול הכיתה. הם חוששים שיטעו או שיצחקו עליהם. אבל ככל שהם מתרגלים לדבר מול קהל, הפחד הזה קטן, וגם אם הם טועים, זה לא נורא כמו שחשבו.","lines":[{"label":"צעד 1 — הנושא","value":"פחד לדבר בכיתה"},{"label":"צעד 2 — המסר","value":"הפחד הזה יורד עם תרגול"},{"label":"צעד 3 — הרעיון המרכזי במשפט אחד","value":"פחד לדבר בכיתה הוא דבר נפוץ, אבל הוא יורד ככל שמתרגלים"}]}]},{"title":"זיהוי נושא ומסר","gate":{"lines":["בחרו 4 מתוך 7 הפסקאות שלמטה. את השאר השאירו ריק — אין צורך לסמן שדילגתם.","אם תענו על יותר מ-4 פסקאות, זה יסומן למורה כמאמץ נוסף וייתכן בונוס בציון."],"seconds":10},"group":{"required":4,"itemNoun":"פסקאות","bonusAboveRequired":true,"items":[{"id":"p1.1","label":"פסקה 1","text":"הרבה תלמידים מפחדים לדבר מול הכיתה. הם חוששים שיטעו או שיצחקו עליהם. אבל ככל שהם מתרגלים לדבר מול קהל, הפחד הזה קטן, וגם אם הם טועים, זה לא נורא כמו שחשבו.","questions":[{"kind":"choice","id":"p1.1.topic","prompt":"מהו הנושא של הפסקה?","options":[{"text":"איך לדבר יפה מול קהל","correct":false,"why":"לא מוזכר בפסקה."},{"text":"פחד לדבר מול כיתה","correct":true},{"text":"חברים בכיתה","correct":false,"why":"לא קשור לפסקה."}]},{"kind":"choice","id":"p1.1.message","prompt":"מהו המסר של הפסקה?","options":[{"text":"אסור לפחד לדבר מול כיתה","correct":false,"why":"לא זה מה שנאמר בפסקה."},{"text":"הפחד הזה קטן ככל שמתרגלים","correct":true},{"text":"תלמידים תמיד טועים כשהם מדברים","correct":false,"why":"זו רק דוגמה מהפסקה, לא המסר הכולל."}]}]},{"id":"p1.2","label":"פסקה 2","text":"הרבה בני נוער משתמשים בטלפון הנייד ממש לפני השינה. האור הכחול מהמסך מבלבל את המוח וגורם לו לחשוב שעדיין יום. בגלל זה קשה יותר להירדם, והשינה נהיית פחות איכותית.","questions":[{"kind":"choice","id":"p1.2.topic","prompt":"מהו הנושא של הפסקה?","options":[{"text":"איך המוח עובד","correct":false,"why":"רחב מדי — הפסקה לא עוסקת בכל פעולת המוח."},{"text":"אור כחול במסכים","correct":false,"why":"פרט צר מדי מתוך הפסקה."},{"text":"שימוש בטלפון לפני השינה","correct":true}]},{"kind":"choice","id":"p1.2.message","prompt":"מהו המסר של הפסקה?","options":[{"text":"אסור להשתמש בטלפון בכלל","correct":false,"why":"הפרזה — הפסקה לא אומרת זאת."},{"text":"טלפון לפני השינה פוגע באיכות השינה","correct":true},{"text":"המוח תמיד חושב שהיום עדיין יום","correct":false,"why":"פרט שהוצא מהקשרו."}]}]},{"id":"p1.3","label":"פסקה 3","text":"יותר ויותר בני נוער עובדים בעבודות חלקיות כבר בתיכון. הסיבה העיקרית היא הרצון להרוויח כסף עצמאי ולא להיות תלויים בהורים. עבודה כזו גם מלמדת אחריות ומשמעת, כי התלמיד צריך להגיע בזמן ולעמוד בהתחייבויות.","questions":[{"kind":"choice","id":"p1.3.topic","prompt":"מהו הנושא של הפסקה?","options":[{"text":"משמעת בעבודה","correct":false,"why":"פרט צר מדי מתוך הפסקה."},{"text":"עבודה חלקית של בני נוער בתיכון","correct":true},{"text":"תלות כלכלית בהורים","correct":false,"why":"מוזכר, אבל אינו הנושא."}]},{"kind":"choice","id":"p1.3.message","prompt":"מהו המסר של הפסקה?","options":[{"text":"כל בני הנוער חייבים לעבוד","correct":false,"why":"הפרזה — לא נאמר בפסקה."},{"text":"הורים תמיד תומכים כלכלית","correct":false,"why":"לא קשור למה שנאמר."},{"text":"עבודה חלקית עוזרת לעצמאות כלכלית ומלמדת אחריות","correct":true}]}]},{"id":"p1.4","label":"פסקה 4","text":"כשגולשים ברשתות החברתיות, קל להתחיל להשוות את החיים שלנו לחיים שאנשים אחרים מציגים שם. הבעיה היא שרוב האנשים מראים רק את הרגעים הכי טובים שלהם. בגלל זה ההשוואה הזו יכולה לגרום לנו להרגיש רע, בלי סיבה אמיתית.","questions":[{"kind":"choice","id":"p1.4.topic","prompt":"מהו הנושא של הפסקה?","options":[{"text":"רגעים טובים בחיים","correct":false,"why":"פרט מתוך הפסקה, לא הנושא."},{"text":"איך מרגישים רע","correct":false,"why":"רחב מדי."},{"text":"השוואה בין החיים שלנו לרשתות חברתיות","correct":true}]},{"kind":"choice","id":"p1.4.message","prompt":"מהו המסר של הפסקה?","options":[{"text":"כל האנשים ברשתות משקרים","correct":false,"why":"הפרזה — לא נאמר בפסקה."},{"text":"השוואה לרשתות חברתיות יכולה לגרום לנו להרגיש רע, למרות שהיא לא הוגנת","correct":true},{"text":"אסור להשתמש ברשתות חברתיות","correct":false,"why":"לא זה מה שנאמר."}]}]},{"id":"p1.5","label":"פסקה 5","text":"תלמידים רבים לומדים עד שעה מאוחרת בלילה שלפני מבחן. מחקרים מראים שבזמן השינה המוח מארגן ושומר את החומר שלמדנו באותו יום. משום כך, שינה מספקת נחשבת לחלק ממש מתהליך הלמידה, ולא רק למנוחה.","questions":[{"kind":"choice","id":"p1.5.topic","prompt":"מהו הנושא של הפסקה?","options":[{"text":"כמה שעות ללמוד","correct":false,"why":"פרט, לא הנושא."},{"text":"שינה לפני מבחנים","correct":true},{"text":"איך לזכור חומר טוב יותר","correct":false,"why":"זווית אחרת ממה שהפסקה עוסקת בו."}]},{"kind":"choice","id":"p1.5.message","prompt":"מהו המסר של הפסקה?","options":[{"text":"אסור ללמוד בלילה בכלל","correct":false,"why":"הפרזה."},{"text":"המוח זוכר הכל גם בלי שינה","correct":false,"why":"סותר את מה שכתוב בפסקה."},{"text":"שינה מספקת היא חלק מתהליך הלמידה עצמו","correct":true}]}]},{"id":"p1.6","label":"פסקה 6","text":"עבודה בקבוצות בכיתה דורשת מכל תלמיד לקחת חלק ולתרום את שלו. כדי שהעבודה תצליח, חשוב לחלק תפקידים בבירור מההתחלה ולתקשר על ההתקדמות. כשזה עובד טוב, כל הקבוצה מרוויחה זמן ותוצאה טובה יותר.","questions":[{"kind":"choice","id":"p1.6.topic","prompt":"מהו הנושא של הפסקה?","options":[{"text":"חלוקת תפקידים","correct":false,"why":"פרט מתוך הפסקה."},{"text":"הצלחה בלימודים","correct":false,"why":"רחב מדי."},{"text":"עבודה בקבוצות בכיתה","correct":true}]},{"kind":"choice","id":"p1.6.message","prompt":"מהו המסר של הפסקה?","options":[{"text":"כל התלמידים תמיד תורמים באותה מידה","correct":false,"why":"הפרזה."},{"text":"כשעובדים בשיתוף פעולה נכון, כל הקבוצה מרוויחה","correct":true},{"text":"עבודת קבוצה תמיד מבזבזת זמן","correct":false,"why":"שגוי לגמרי — הפוך מהפסקה."}]}]},{"id":"p1.7","label":"פסקה 7","text":"הרבה בני נוער שותים משקאות אנרגיה כדי להישאר ערניים ביום לימודים ארוך. המשקאות נותנים תחושת ערנות מהירה, אבל האפקט חולף מהר ולפעמים משאיר עייפות גדולה עוד יותר. שינה סדירה נותנת אנרגיה יציבה בהרבה.","questions":[{"kind":"choice","id":"p1.7.topic","prompt":"מהו הנושא של הפסקה?","options":[{"text":"שינה סדירה","correct":false,"why":"מוזכר בפסקה, אבל אינו הנושא."},{"text":"משקאות אנרגיה","correct":true},{"text":"ימי לימודים ארוכים","correct":false,"why":"רקע, לא הנושא."}]},{"kind":"choice","id":"p1.7.message","prompt":"מהו המסר של הפסקה?","options":[{"text":"אסור לשתות משקאות אנרגיה בכלל","correct":false,"why":"הפרזה."},{"text":"שינה לא עוזרת לאנרגיה","correct":false,"why":"סותר את הפסקה."},{"text":"משקאות אנרגיה נותנים אנרגיה זמנית בלבד, ואז מעייפים עוד יותר","correct":true}]}]}]}},{"title":"צ''ק-ליסט וניסוחים אמיתיים","intro":"לפניכם ניסוחים אמיתיים ואנונימיים של תלמידים לרעיון המרכזי של הפסקה שלמטה. לכל ניסוח החליטו אם הוא תקין, ואם לא — סמנו אילו סעיפים מהצ''ק-ליסט הוא מפר.","blocks":[{"kind":"checklist","title":"צ''ק-ליסט לניסוח רעיון מרכזי","items":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}]},{"kind":"text","title":"הפסקה שעליה נכתבו הניסוחים","body":"התחלות חדשות תמיד מלוות בתחושה של חוסר ודאות. אנשים רבים חוששים משינוי כי הוא מוציא אותם מאזור הנוחות שלהם וגורם להם להתמודד עם דברים לא מוכרים. למרות הפחד, שינוי יכול להיות גם הזדמנות ללמוד דברים חדשים, להכיר אנשים שונים ולגלות יכולות שלא ידענו שיש לנו."}],"questions":[{"kind":"judge","id":"p2.1","quote":"רבים אינם חוששים מ''התחלה'' עצמה, אלא מהשינוי שמתלווה אליה.","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":false,"correctViolations":["own"],"explain":"זהו משפט שהועתק מהטקסט, ולא ניסוח במילים שלכם."},{"kind":"judge","id":"p2.2","quote":"שינוי","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":false,"correctViolations":["full"],"explain":"מילה בודדת — זה נושא בלבד, בלי מסר ובלי משפט שלם."},{"kind":"judge","id":"p2.3","quote":"פחד וחוסר ודאות בהתחלות חדשות","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":true,"correctViolations":[],"explain":"ניסוח תמציתי ומדויק במילים של הכותב/ת, שמתאים לכל הפסקה."},{"kind":"judge","id":"p2.4","quote":"שינוי הוא חלק טבעי מהחיים ולא צריך לפחד ממנו","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":false,"correctViolations":["fromText"],"explain":"עצה כללית שלא נובעת ישירות מהפסקה."},{"kind":"judge","id":"p2.5","quote":"הפסקה עוסקת בעיקר בהשפעת השינוי והקושי להסתגל אליו, ולא בהתחלה עצמה","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":true,"correctViolations":[],"explain":"משפט שלם במילים עצמאיות, שמכסה את כל הפסקה."},{"kind":"judge","id":"p2.6","quote":"כח","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":false,"correctViolations":["full"],"explain":"מילה בודדת — קצר מדי, אין בה מסר."},{"kind":"judge","id":"p2.7","quote":"שלכל שינוי יש גם צד טוב ולא רק רע","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":true,"correctViolations":[],"explain":"משפט שלם שמנוסח באופן עצמאי ומתאים לכלל הפסקה."},{"kind":"judge","id":"p2.8","quote":"האם כדאי לפחוד משינוי?","okLabel":"נכון","badLabel":"לא נכון","rules":[{"id":"full","text":"כתבו משפט שלם, לא מילה בודדת"},{"id":"own","text":"כתבו במילים שלכם — לא להעתיק מהטקסט"},{"id":"whole","text":"המשפט מתאים לכל הפסקה, לא רק לדוגמה אחת מתוכה"},{"id":"claim","text":"כתבו משפט קובע — רעיון מרכזי לא יכול להיות מנוסח כשאלה"},{"id":"fromText","text":"המשפט נובע מהפסקה עצמה, ולא עצה כללית מבחוץ"}],"correctOk":false,"correctViolations":["claim"],"explain":"זו שאלה ולא קביעה — רעיון מרכזי צריך להיות מנוסח כמשפט קובע."}]},{"title":"ניסוח עצמאי","gate":{"lines":["בחרו 2 מתוך 4 הפסקאות. את השאר השאירו ריק.","אם תענו על יותר מ-2, זה יסומן למורה כמאמץ נוסף וייתכן בונוס בציון."],"seconds":10},"group":{"required":2,"itemNoun":"פסקאות","bonusAboveRequired":true,"items":[{"id":"p3.a","label":"פסקה א","text":"אימוץ כלב נשמע כמו רעיון מושלם לכל מי שאוהב בעלי חיים, אבל זו גם אחריות גדולה. כלב צריך טיפולים וטיולים בכל יום, גם כשקר או עייף. מי שלא מוכן להשקיע בזה זמן קבוע, כדאי שיחשוב פעמיים לפני שהוא מביא כלב הביתה.","questions":[{"kind":"open","id":"p3.a.text","prompt":"נסחו את הרעיון המרכזי של הפסקה במשפט אחד שלם, במילים שלכם.","rows":3,"minChars":25}]},{"id":"p3.b","label":"פסקה ב","text":"למידה מקוונת מאפשרת לתלמידים ללמוד מכל מקום ובקצב שלהם. אבל היא גם דורשת המון משמעת עצמית, כי אין מורה שעומד לידך ומוודא שאתה מתקדם. בלי משמעת כזו, קל מאוד לפגר אחורה.","questions":[{"kind":"open","id":"p3.b.text","prompt":"נסחו את הרעיון המרכזי של הפסקה במשפט אחד שלם, במילים שלכם.","rows":3,"minChars":25}]},{"id":"p3.c","label":"פסקה ג","text":"הרבה אנשים חושבים שמחזור הוא פעולה קטנה שלא באמת משנה, אבל כשהרבה אנשים עושים אותה יחד, ההשפעה מצטברת ונהיית משמעותית. מיון פסולת לוקח רק כמה שניות נוספות, אבל הוא יכול לחסוך משאבים רבים בטווח הארוך.","questions":[{"kind":"open","id":"p3.c.text","prompt":"נסחו את הרעיון המרכזי של הפסקה במשפט אחד שלם, במילים שלכם.","rows":3,"minChars":25}]},{"id":"p3.d","label":"פסקה ד","text":"תלמידים שמשחקים בקבוצת ספורט לומדים הרבה יותר מאשר רק את המשחק עצמו. הם לומדים לעבוד יחד עם אחרים, להתמודד עם הפסדים, ולהתמיד גם כשקשה. מיומנויות כאלה נשארות איתם הרבה אחרי שהם מפסיקים לשחק.","questions":[{"kind":"open","id":"p3.d.text","prompt":"נסחו את הרעיון המרכזי של הפסקה במשפט אחד שלם, במילים שלכם.","rows":3,"minChars":25}]}]}}],"feedbackIntro":"עוד חמש שאלות קצרות, ואז מגישים את המשימה.","feedbackQuestions":[{"kind":"scale","id":"feedback.clarity_scale","prompt":"עד כמה ההבדל בין נושא למסר ברור לך עכשיו?"},{"kind":"scale","id":"feedback.learning_scale","prompt":"עד כמה הרגשת שהתרגול הזה שיפר לך את ניסוח הרעיון המרכזי?"},{"kind":"scale","id":"feedback.explanation_scale","prompt":"עד כמה ההסבר בעמוד הראשון (שלושת הצעדים) עזר לך?"},{"kind":"open","id":"feedback.hardest_part","prompt":"מה היה החלק הקשה ביותר בתרגול?","rows":2},{"kind":"open","id":"feedback.still_unclear","prompt":"דבר אחד שעדיין לא ברור לי הוא...","rows":2}]}'::jsonb,
    engine = 'runner',
    updated_at = now()
where engine = 'legacy-mi';

-- 2. העתקת התשובות.
insert into public.runner_answers (task_id, student_id, item_key, answer_text, created_at, updated_at)
select a.task_id, a.student_id, a.question_id, a.answer_text, a.created_at, a.updated_at
from public.nb10_answers a
join public.tasks t on t.id = a.task_id
on conflict (task_id, student_id, item_key) do nothing;

insert into public.runner_answers (task_id, student_id, item_key, answer_text, created_at, updated_at)
select a.task_id, a.student_id, a.item_key, a.answer_text, a.created_at, a.updated_at
from public.mi_answers a
join public.tasks t on t.id = a.task_id
on conflict (task_id, student_id, item_key) do nothing;

-- 3. העתקת המשוב המסכם כתשובות עם מפתחות feedback.*
insert into public.runner_answers (task_id, student_id, item_key, answer_text)
select f.task_id, f.student_id, v.item_key, v.answer_text
from public.nb10_feedback f
join public.tasks t on t.id = f.task_id
cross join lateral (values
  ('feedback.clarity_scale', coalesce(f.clarity_scale::text, '')),
  ('feedback.learning_scale', coalesce(f.learning_scale::text, '')),
  ('feedback.assistant_scale', coalesce(f.assistant_scale::text, '')),
  ('feedback.compare_lesson', coalesce(f.compare_lesson, '')),
  ('feedback.help_page_usage', coalesce(f.help_page_usage, '')),
  ('feedback.still_unclear', coalesce(f.still_unclear, ''))
) as v(item_key, answer_text)
where v.answer_text <> ''
on conflict (task_id, student_id, item_key) do nothing;

insert into public.runner_answers (task_id, student_id, item_key, answer_text)
select f.task_id, f.student_id, v.item_key, v.answer_text
from public.mi_feedback f
join public.tasks t on t.id = f.task_id
cross join lateral (values
  ('feedback.clarity_scale', coalesce(f.clarity_scale::text, '')),
  ('feedback.learning_scale', coalesce(f.learning_scale::text, '')),
  ('feedback.explanation_scale', coalesce(f.explanation_scale::text, '')),
  ('feedback.hardest_part', coalesce(f.hardest_part, '')),
  ('feedback.still_unclear', coalesce(f.still_unclear, ''))
) as v(item_key, answer_text)
where v.answer_text <> ''
on conflict (task_id, student_id, item_key) do nothing;

-- 4. העתקת ההגשות.
insert into public.runner_submissions (task_id, student_id, submitted_at)
select s.task_id, s.student_id, s.submitted_at
from public.nb10_submissions s join public.tasks t on t.id = s.task_id
on conflict (task_id, student_id) do nothing;

insert into public.runner_submissions (task_id, student_id, submitted_at)
select s.task_id, s.student_id, s.submitted_at
from public.mi_submissions s join public.tasks t on t.id = s.task_id
on conflict (task_id, student_id) do nothing;

-- 5. העתקת הערות וציונים של המורה.
-- הכפילויות הישנות נפתרות: נשמרת ההערה המעודכנת ביותר לכל פריט.
insert into public.runner_notes (task_id, student_id, item_key, note, score, created_at, updated_at)
select distinct on (n.task_id, n.student_id, coalesce(n.question_id, ''))
       n.task_id, n.student_id, n.question_id, n.note, n.score, n.created_at, n.updated_at
from public.nb10_notes n join public.tasks t on t.id = n.task_id
order by n.task_id, n.student_id, coalesce(n.question_id, ''), n.updated_at desc;

insert into public.runner_notes (task_id, student_id, item_key, note, score, created_at, updated_at)
select distinct on (n.task_id, n.student_id, coalesce(n.item_key, ''))
       n.task_id, n.student_id, n.item_key, n.note, n.score, n.created_at, n.updated_at
from public.mi_notes n join public.tasks t on t.id = n.task_id
order by n.task_id, n.student_id, coalesce(n.item_key, ''), n.updated_at desc;

-- 6. משימת ההדגמה כבר לא נחוצה — המשימה האמיתית עצמה רצה על המנוע.
delete from public.tasks where title = 'התחלות חדשות (הדגמת מנוע JSON)' and engine = 'runner';

-- 7. הרשאות ההקראה של המשימה הישנה עוברות לטבלה המשותפת.
insert into public.student_task_speech (student_id, task_id, allowed)
select s.student_id, s.task_id, s.allowed
from public.mi_student_speech s join public.tasks t on t.id = s.task_id
on conflict (student_id, task_id) do update set allowed = excluded.allowed;
